# OSMIUM POLICY ENGINE
. (Join-Path $PSScriptRoot "Osmium-Audit.ps1")
$script:OsmiumToolPolicies = @{ respond = @{ Risk = "None"; Approval = $false }; system_status = @{ Risk = "ReadOnly"; Approval = $false }; find_large_files = @{ Risk = "ReadOnly"; Approval = $false }; search_files = @{ Risk = "ReadOnly"; Approval = $false }; organise_preview = @{ Risk = "ReadOnly"; Approval = $false }; create_folder = @{ Risk = "Low"; Approval = $true } }
function Get-OsmiumToolPolicy { param([string]$Tool) if (-not $script:OsmiumToolPolicies.ContainsKey($Tool)) { throw "POLICY DENIED: Unknown tool: $Tool" }; return $script:OsmiumToolPolicies[$Tool] }
function Test-OsmiumToolPolicy { param([string]$Tool) try { $p=Get-OsmiumToolPolicy $Tool; [pscustomobject]@{Allowed=$true;Tool=$Tool;Risk=$p.Risk;RequiresApproval=$p.Approval;Reason="Registered"} } catch { [pscustomobject]@{Allowed=$false;Tool=$Tool;Risk="Unknown";RequiresApproval=$true;Reason=$_.Exception.Message} } }
function Request-OsmiumApproval { param([string]$Tool,[string]$Target="",[object]$Arguments=$null) $p=Get-OsmiumToolPolicy $Tool; $fingerprint=""; try { $argJson=ConvertTo-Json -InputObject $Arguments -Depth 10 -Compress -ErrorAction Stop; $payload=$Tool+"|"+$Target+"|"+$argJson; $sha=[Security.Cryptography.SHA256]::Create(); try { $fingerprint=([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($payload)))).Replace("-","") } finally { $sha.Dispose() }; if (-not $p.Approval) { return [pscustomobject]@{Approved=$true;Fingerprint=$fingerprint;Risk=$p.Risk;Tool=$Tool;Target=$Target} }; Write-Host "OSMIUM CENTRAL APPROVAL REQUIRED" -ForegroundColor Yellow; Write-Host "Operation: $Tool"; if ($Target) { Write-Host "Target: $Target" }; Write-Host "Arguments fingerprint: $fingerprint"; $approved=(Read-Host "Approve this exact operation? (y/N)") -match "^(?i:y|yes)$"; $decision=if($approved){"Approved"}else{"Rejected"}; $outcome=if($approved){"Authorized"}else{"Denied"}; Write-OsmiumAuditEvent -EventType "APPROVAL" -Tool $Tool -Target $Target -Risk $p.Risk -Fingerprint $fingerprint -Decision $decision -Outcome $outcome -Details "Central approval decision" | Out-Null; return [pscustomobject]@{Approved=$approved;Fingerprint=$fingerprint;Risk=$p.Risk;Tool=$Tool;Target=$Target} } catch { Write-Host "APPROVAL/AUDIT FAILURE: $($_.Exception.Message)" -ForegroundColor Red; return [pscustomobject]@{Approved=$false;Fingerprint=$fingerprint;Risk=$p.Risk;Tool=$Tool;Target=$Target} } }; function Confirm-OsmiumOperation { param([string]$Tool,[string]$Target="") return (Request-OsmiumApproval -Tool $Tool -Target $Target) }
